<script setup>
import { computed, onMounted, ref } from 'vue';
import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import Skeleton from 'primevue/skeleton';
import { useRouter } from 'vue-router';
import { useAdminStore } from '../stores/useAdminStore';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('OperatorDashboard');
const router = useRouter();
const adminStore = useAdminStore();
const loading = ref(false);
const refreshing = ref(false);
const error = ref('');
const stats = computed(() => adminStore.stats || { pending_ads_count: 0, pending_kyc_count: 0, today_approved_ads: 0, today_rejected_ads: 0, recent_pending_ads: [] });
const formatMoney = (value) => value ? `${new Intl.NumberFormat('fa-IR').format(value)} میلیون تومان` : 'ثبت نشده';
const formatDate = (value) => value ? new Intl.DateTimeFormat('fa-IR', { dateStyle: 'medium' }).format(new Date(value)) : '-';

async function loadStats() {
    loading.value = !adminStore.statsLoaded;
    refreshing.value = adminStore.statsLoaded;
    error.value = '';
    try { await adminStore.loadOperatorStats(); } catch (exception) { error.value = 'دریافت آمار لحظه‌ای انجام نشد.'; logger.error('loadStats', 'Operator stats request failed', logException(exception)); }
    finally { loading.value = false; refreshing.value = false; }
}

onMounted(loadStats);
</script>

<template>
    <section class="operator-dashboard">
        <header class="operator-dashboard__hero"><div><span class="operator-dashboard__kicker">OPERATION CONTROL CENTER</span><h1>میز کار و داشبورد عملیات</h1><p>خوش‌آمدید {{ adminStore.user?.name || 'اپراتور' }} <b>•</b> وضعیت لحظه‌ای صف‌های بررسی سامانه مستروام</p></div><button class="refresh-button" type="button" :disabled="refreshing" @click="loadStats"><i :class="refreshing ? 'pi pi-spin pi-refresh' : 'pi pi-refresh'"></i><span>به‌روزرسانی</span></button></header>
        <p v-if="error" class="operator-error" role="alert"><i class="pi pi-exclamation-triangle"></i>{{ error }}</p>
        <div v-if="loading" class="operator-kpis"><Skeleton v-for="index in 4" :key="index" height="126px" borderRadius="12px" /></div>
        <div v-else class="operator-kpis">
            <article class="operator-kpi operator-kpi--amber"><div class="operator-kpi__icon"><i class="pi pi-file-edit"></i></div><div><span>آگهی‌های در انتظار بررسی</span><strong>{{ stats.pending_ads_count }}</strong><button type="button" @click="router.push({ name: 'admin.ads.pending' })">مشاهده صف <i class="pi pi-arrow-left"></i></button></div></article>
            <article class="operator-kpi operator-kpi--blue"><div class="operator-kpi__icon"><i class="pi pi-id-card"></i></div><div><span>مدارک هویتی منتظر تایید</span><strong>{{ stats.pending_kyc_count }}</strong><button type="button" @click="router.push({ name: 'admin.kyc' })">صف احراز هویت <i class="pi pi-arrow-left"></i></button></div></article>
            <article class="operator-kpi operator-kpi--green"><div class="operator-kpi__icon"><i class="pi pi-check-circle"></i></div><div><span>آگهی تایید شده امروز</span><strong>{{ stats.today_approved_ads }}</strong><small>به‌روزرسانی از دیتابیس</small></div></article>
            <article class="operator-kpi operator-kpi--red"><div class="operator-kpi__icon"><i class="pi pi-times-circle"></i></div><div><span>آگهی رد شده امروز</span><strong>{{ stats.today_rejected_ads }}</strong><small>به‌روزرسانی از دیتابیس</small></div></article>
        </div>
        <div class="operator-workspace"><section class="operator-queue"><div class="section-heading"><div><span>صف سریع بررسی</span><h2>۵ آگهی اخیر در انتظار</h2></div><RouterLink :to="{ name: 'admin.ads.pending' }">مشاهده همه <i class="pi pi-arrow-left"></i></RouterLink></div><DataTable :value="stats.recent_pending_ads" dataKey="id" responsiveLayout="scroll" stripedRows emptyMessage="صف بررسی خالی است."><Column field="title" header="عنوان آگهی"><template #body="slotProps"><strong class="ad-title">{{ slotProps.data.title }}</strong><small>{{ slotProps.data.user?.name || 'کاربر' }}</small></template></Column><Column field="bank.name" header="بانک"><template #body="slotProps">{{ slotProps.data.bank?.name || '-' }}</template></Column><Column field="loan_amount" header="مبلغ وام"><template #body="slotProps">{{ formatMoney(slotProps.data.loan_amount) }}</template></Column><Column field="created_at" header="ثبت"><template #body="slotProps">{{ formatDate(slotProps.data.created_at) }}</template></Column><Column header="عملیات"><template #body="slotProps"><button class="table-action" type="button" @click="router.push({ name: 'admin.ads.pending', query: { id: slotProps.data.id } })">بررسی <i class="pi pi-angle-left"></i></button></template></Column></DataTable></section><aside class="operator-notes"><div class="section-heading"><div><span>مرکز اعلان</span><h2>یادداشت‌های اپراتوری</h2></div><i class="pi pi-bell"></i></div><div class="note"><i class="pi pi-shield"></i><p><strong>امنیت فعال است</strong><br />تمام عملیات بررسی با شناسه کاربری شما ثبت می‌شود.</p></div><div class="note"><i class="pi pi-clock"></i><p><strong>اولویت بررسی</strong><br />پرونده‌های قدیمی‌تر را ابتدا بررسی کنید.</p></div><div class="note note--muted"><i class="pi pi-info-circle"></i><p>آمارها با هر بار ورود یا رفرش دستی از دیتابیس خوانده می‌شوند.</p></div></aside></div>
    </section>
</template>

